<style>
.repo-shell{--repo-navy:#071e45;--repo-blue:#1557a6;--repo-blue-2:#2774c8;--repo-gold:#d79a21;--repo-green:#17a065;--repo-red:#ef5a5a;--repo-amber:#e9a32b;--repo-violet:#7c64d8;--repo-text:#102744;--repo-muted:#6e7f96;--repo-line:#dde6f1;--repo-soft:#f6f9fd;max-width:1220px;margin:0 auto;color:var(--repo-text);font-family:inherit}
