dding:11px 13px;border-top:1px solid #edf2f7}
.repo-empty{min-height:320px;padding:38px 20px;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center}.repo-empty-art{width:180px;height:115px;margin-bottom:5px}.repo-empty h2{margin:0;color:var(--repo-navy);font-size:13px;font-weight:800}.repo-empty p{margin:5px 0 14px;color:#8594a7;font-size:9.5px}.repo-empty .repo-button{min-height:36px}
