align-items:center;gap:8px;border-radius:7px;color:#47709c;background:#eef6ff;font-size:8.5px}.repo-auto-note svg{width:14px;height:14px;flex:0 0 14px;fill:none;stroke:#2774c8;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
