.repo-topics-grid{display:grid;grid-template-columns:330px minmax(0,1fr);align-items:start;gap:14px}.repo-topic-form{padding:14px}.repo-field-row{display:grid;grid-template-columns:1fr 1fr;gap:9px}.repo-topic-form .repo-field{margin-bottom:11px}.repo-topic-form .repo-field input,.repo-topic-form .repo-field select{margin:0}.repo-topic-form .repo-field textarea{min-height:84px}.repo-topic-list-head{min-height:58px;padding:11px 13px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid #e8eef5}.repo-topic-list-head h2{margin:0;color:var(--repo-navy);font-size:12px}.repo-topic-list-head span{display:block;margin-top:3px;color:#8594a7;font-size:8.5px}.repo-topic-search{width:min(230px,50%);height:36px;padding:0 9px;display:flex;align-items:center;gap:7px;border:1px solid var(--repo-line);border-radius:7px;background:#fff}.repo-topic-search svg{width:14px;height:14px;fill:none;stroke:#8392a4;stroke-width:2;stroke-linecap:round}.repo-topic-search input{min-width:0;flex:1;border:0;outline:0;background:transparent;color:var(--repo-text);font-size:9.5px}.repo-topic-search a{color:var(--repo-blue);font-size:8.5px;font-weight:700;text-decoration:none}.repo-topic-row{padding:11px 13px;display:grid;grid-template-columns:34px minmax(0,1fr) auto;align-items:center;gap:9px;border-bottom:1px solid #edf2f7}.repo-topic-mark{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;color:#276bb2;background:#eaf3fd;font-size:8px;font-weight:800}.repo-topic-copy{min-width:0}.repo-topic-meta{display:flex;align-items:center;gap:5px;color:#7890a9;font-size:8px;font-weight:700;text-transform:uppercase}.repo-topic-meta i{width:3px;height:3px;border-radius:50%;background:#bdc8d4}.repo-topic-copy h3{margin:4px 0;color:#203957;font-size:10.5px}.repo-topic-copy p{margin:0;overflow:hidden;color:#8997a8;font-size:8.5px;text-overflow:ellipsis;white-space:nowrap}.repo-topic-status{padding:4px 6px;border-radius:999px;color:#147247;background:#eaf